// === Tab: mySketch ===
let font
let chars = []
let expandStroke
let expandFill
let aberration

async function setup() {
	createCanvas(800, 800, WEBGL)
	pixelDensity(2)
	font = await loadFont('https://fonts.gstatic.com/s/sourcecodepro/v31/HI_diYsKILxRpg3hIP6sJ7fM7PqPMcMnZFqUwX28DP6QhM5hTXUcdJg.ttf')
	textAlign(CENTER, CENTER)
	textSize(20)

	for (let i = 0; i < 256; i++) {
		const str = String.fromCharCode(i)
		if (/\s/.exec(str)) {
			chars.push(undefined)
		} else {
			chars.push(font.textToModel(str, 0, 0, { sampleFactor: 0.5, extrude: 5 }))
		}
	}

	expandStroke = baseStrokeShader().modify(material)
	expandFill = baseMaterialShader().modify(material)
	aberration = baseFilterShader().modify(() => {
		const mouse = uniformVec2(() => [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height])
		getColor((inputs, canvasContent) => {
			return [
				getTexture(canvasContent, (inputs.texCoord - mouse)*1 + mouse).r,
				getTexture(canvasContent, (inputs.texCoord - mouse)*0.99 + mouse).g,
				getTexture(canvasContent, (inputs.texCoord - mouse)*0.98 + mouse).b,
				1
			]
		})
	})
}

function material() {
	var mouse = uniformVec2(() => [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2])
	getWorldInputs((inputs) => {
		let fromMouse = inputs.position.xy - mouse
		const distFromMouse = length(fromMouse)
		fromMouse /= (distFromMouse + 0.001)

		inputs.position.xy += fromMouse * (5000 / (100 + pow(distFromMouse, 0.15)/20))

		return inputs
	})
}

function draw() {
	background(255)
	orbitControl()

	push()
	shader(expandFill)
	strokeShader(expandStroke)
	let i = 0
	for (let x = 0; x < 16; x++) {
		for (let y = 0; y < 16; y++) {
			if (chars[i]) {
				push()
				translate((x-8)*20, (y-8)*20)
				model(chars[i])
				pop()
			}
			i++
		}
	}
	pop()

	filter(aberration)
}

